sources.payments:
import { webhook } from adapters
import { StripeHook } from credentials

stripe = connect webhook using StripeHook

type Currency = <"usd" | "eur">

node Charge {
  id: <text>
}

node Payment extends Charge {
  amount: <number>
  currency: <Currency>
  note: <text | null>
  meta: <json>
  node card {
    last4: <text>
  }
  node lines {
    sku: <text>
  }
}

node `Odd Name` {
  ok: <boolean>
}

function paid(p: <Payment>) {
}

listen to stripe-[:Requests]-><Payment> fire paid
